// Parse incoming OS data
const data = $input.first().json;

// Validate required fields
if (!data.os_number || !data.pts) {
  throw new Error('Campos obrigatorios faltando: os_number, pts');
}

// Format date for filename
const dateStr = (data.data || '').replace(/\//g, '-');

// Prepare structured data
return {
  ...data,
  filename: `OS_${data.os_number}_${dateStr}.pdf`,
  timestamp: new Date().toISOString()
};

const prev = $input.first().json;
const llmResponse = $('OpenRouter — Resumir').first().json;
const descResumida = llmResponse?.choices?.[0]?.message?.content || prev.descricao_detalhada || prev.descricao;

return { ...prev, descricao_resumida: descResumida.trim() };

const data = $input.first().json;

// Build HTML report
const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head><meta charset="UTF-8"><style>
  @page { margin: 15mm; size: A4; }
  body { font-family: Arial, sans-serif; color: #1f2937; font-size: 11px; }
  .page { page-break-after: always; }
  .page:last-child { page-break-after: auto; }
  .header { border-bottom: 2px solid #1e40af; padding-bottom: 10px; margin-bottom: 14px; }
  .header h1 { color: #1e40af; font-size: 16px; margin: 0 0 2px; }
  .header .sub { color: #6b7280; font-size: 10px; }
  .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  .field { margin-bottom: 10px; }
  .field label { font-size: 8px; color: #6b7280; text-transform: uppercase; font-weight: bold; }
  .field .value { font-size: 11px; font-weight: 500; }
  .section-title { font-size: 13px; color: #1e40af; font-weight: bold; border-bottom: 1px solid #e5e7eb; padding-bottom: 6px; margin: 14px 0 8px; }
  .status-finalizado { background: #dcfce7; color: #166534; padding: 2px 8px; border-radius: 12px; font-size: 9px; font-weight: 600; }
  .photos-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
  .photo-entry img { max-width: 100%; border: 1px solid #ddd; border-radius: 4px; }
  .photo-entry p { font-size: 9px; color: #666; margin: 2px 0 0; }
  .signature-img { max-width: 220px; }
</style></head><body>

<div class="page">
  <div class="header">
    <h1>UTE Pernambuco III</h1>
    <div class="sub">Relatorio de Ordem de Servico — OS ${data.os_number || ''}</div>
  </div>

  <div class="grid">
    <div class="field"><label>OS No</label><div class="value">${data.os_number || ''}</div></div>
    <div class="field"><label>PTS No</label><div class="value">${data.pts || ''}</div></div>
    <div class="field"><label>Data</label><div class="value">${data.data || ''}</div></div>
    <div class="field"><label>Status</label><div class="value"><span class="status-finalizado">Finalizado</span></div></div>
    <div class="field"><label>Local / TAG</label><div class="value">${data.local || ''}</div></div>
    <div class="field"><label>Supervisor</label><div class="value">${data.supervisor || ''}</div></div>
    <div class="field"><label>Hora Inicial</label><div class="value">${data.hora_inicial || ''}</div></div>
    <div class="field"><label>Hora Final</label><div class="value">${data.hora_final || ''}</div></div>
    <div class="field"><label>Horimetro</label><div class="value">${data.horimetro || '—'}</div></div>
  </div>

  <div class="field" style="margin-top:8px"><label>Tecnicos</label><div class="value">${(data.tecnicos || []).join(', ')}</div></div>

  <div class="section-title">Descricao</div>
  <div class="field"><label>Resumo</label><div class="value">${data.descricao || ''}</div></div>
  <div class="field"><label>Resumo Tecnico (IA)</label><div class="value">${data.descricao_resumida || ''}</div></div>
  <div class="field"><label>Descricao Detalhada</label><div class="value" style="white-space:pre-wrap">${data.descricao_detalhada || ''}</div></div>
  ${data.observacoes ? '<div class="field"><label>Observacoes</label><div class="value">' + data.observacoes + '</div></div>' : ''}
  ${data.assinatura ? '<div class="section-title">Assinatura</div><img src="' + data.assinatura + '" class="signature-img">' : ''}
</div>

${(data.fotos || []).length ? '<div class="page"><div class="header"><h1>Relatorio Fotografico</h1></div><div class="photos-grid">' + data.fotos.map((f,i) => '<div class="photo-entry"><img src="' + f.base64 + '"><p>' + (f.descricao || 'Foto ' + (i+1)) + '</p></div>').join('') + '</div></div>' : ''}

${data.foto_pts ? '<div class="page"><div class="header"><h1>Permissao de Trabalho — Anexo</h1></div><img src="' + data.foto_pts + '" style="max-width:100%"></div>' : ''}

</body></html>`;

return { html, filename: data.filename, ...data };

const pdfData = $input.first().json.data; // base64 PDF
const meta = $('Build HTML Report').first().json;

return {
  file_name: meta.filename,
  file_data: pdfData,
  mime_type: 'application/pdf'
};

